-- 00115_menopause_condition_rules.sql — Menopause messages and condition nudges as message rules (T-M10-09, D-166;
-- SPEC §5.4.1). Data only (no schema change), so no Laravel twin: Laravel never serves the inbox.
--
-- One approved message rule per message of the retired per-request engines (D-43 menopause messages, D-41 condition
-- nudges): rule_key meno.<name> / cond.<name>. Warnings and reminders go to the alerts_inbox slot, the menopause stage
-- tips to daily_advice. The rows are generated from internal/messages/menomessages and
-- internal/messages/conditionnudges (Defs + copy/<code>.json: the default language fa as the base,
-- content.translations.en) and pinned by the migration int test; the copy is today's (menopause_messages /
-- condition_nudges embedded copy, catalog meno_alerts postmenopausal_bleeding and meno_tips stage_*) with the
-- variables renamed to the meno_* / cond_* evidence variables. meno.postmenopausal_bleeding keeps today's level
-- (follow_up, no modal) and is locked; every rule is listed for the advisor in docs/engine-v6/clinical-signoff.md §E.
-- ON DUPLICATE KEY keeps a database whose rules were already seeded (or edited) as it is.
-- Down removes the inbox rows of these rules (the adapters wrote them), then the seeded rules.

-- +goose Up
-- +goose StatementBegin
INSERT INTO `message_rules` (rule_key, title, level, kind, priority, placement, content, conditions, exceptions,
  variants_enabled, ab_split, cap_count, cap_period, cooldown_days, audience_percent, status, is_active, version,
  approved_version, locked, created_at, updated_at)
VALUES
('meno.postmenopausal_bleeding', 'Menopause: bleeding after menopause', 'worth_followup', 'clinical', 700, 'alerts_inbox', '{"a":{"title":"خونریزی بعد از یائسگی","body":"هر خونریزی یا لکه‌بینی، حتی کم، بعد از ۱۲ ماه قطع پریود باید بررسی شود. بیشتر وقت‌ها علت ساده‌ای دارد، اما بررسی زودهنگام مهم است.","cta_label":"این مورد را به پزشک بگو","cta_target":"/menopause/alert"},"seen":"خونریزی یا لکه‌بینی ثبت کردی؛ آخرین بار {meno_bleeding_on}.","confidence":"این از ثبت خودت است، نه تشخیص؛ فقط معاینه می‌تواند علتش را بگوید.","translations":{"en":{"a":{"title":"Bleeding after menopause","body":"Any bleeding or spotting, even a little, 12 months or more after your last period should be checked. Usually the cause is simple, but an early check matters.","cta_label":"Tell your doctor about this","cta_target":"/menopause/alert"},"seen":"You logged bleeding or spotting; the last time on {meno_bleeding_on}.","confidence":"This comes from your own log, not a diagnosis; only an exam can tell the cause."}}}', '[{"op":"and","items":[{"fact":"meno.postmenopausal_bleeding","op":"eq","value":true}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 1, NOW(), NOW()),
('meno.checkup_overdue', 'Menopause: a checkup is overdue', 'suggestion', 'content', 400, 'alerts_inbox', '{"a":{"title":"یک چکاپ عقب افتاده","body":"زمان {meno_overdue_checkup} گذشته است. اگر زودتر نوبت بگیری، برنامه سلامتت مرتب می‌ماند.","cta_label":"دیدن چکاپ‌ها","cta_target":"/checkups"},"translations":{"en":{"a":{"title":"A checkup is overdue","body":"{meno_overdue_checkup} is past its due time. Booking it soon keeps your health plan on track.","cta_label":"See my checkups","cta_target":"/checkups"}}}}', '[{"op":"and","items":[{"fact":"meno.checkups_overdue","op":"gte","value":1}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('meno.score_worsened', 'Menopause: symptom score went up', 'worth_followup', 'clinical', 500, 'alerts_inbox', '{"a":{"title":"امتیاز علائمت بیشتر شده","body":"امتیاز آخرت {meno_score_total} است؛ {meno_score_rise} واحد بیشتر از دفعه قبل ({meno_score_previous}). ببین چه چیزی تغییر کرده و اگر بالا ماند با پزشکت حرف بزن.","cta_label":"دیدن امتیاز","cta_target":"/menopause/score"},"seen":"امتیاز ماهانه‌ات از {meno_score_previous} به {meno_score_total} رسید.","confidence":"این از پرسش‌نامه‌ای است که خودت پر کردی، نه تشخیص.","translations":{"en":{"a":{"title":"Your symptom score went up","body":"Your latest score is {meno_score_total}, {meno_score_rise} points higher than the time before ({meno_score_previous}). Note what changed, and talk to your doctor if it stays high.","cta_label":"See my score","cta_target":"/menopause/score"},"seen":"Your monthly score went from {meno_score_previous} to {meno_score_total}.","confidence":"This comes from the questionnaire you filled in, not a diagnosis."}}}', '[{"op":"and","items":[{"fact":"meno.score_rise","op":"gte","value":4}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('meno.hrt_review', 'Menopause: treatment review coming up', 'suggestion', 'content', 350, 'alerts_inbox', '{"a":{"title":"بازبینی درمان نزدیک است","body":"بازبینی {meno_hrt_name} با پزشکت ({meno_hrt_on}) نزدیک است. حال این مدت و عوارض احتمالی را یادداشت کن تا با خودت ببری.","cta_label":"باز کردن درمان","cta_target":"/menopause/treatment"},"translations":{"en":{"a":{"title":"Treatment review coming up","body":"The review of {meno_hrt_name} with your doctor ({meno_hrt_on}) is coming up. Write down how you have felt and any side effects to take with you.","cta_label":"Open my treatment","cta_target":"/menopause/treatment"}}}}', '[{"op":"and","items":[{"fact":"meno.hrt_review_in_days","op":"between","value":[0,14]}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('meno.checkup_due', 'Menopause: a checkup is due', 'info', 'content', 300, 'alerts_inbox', '{"a":{"title":"وقت یک چکاپ رسیده","body":"زمان {meno_due_checkup} رسیده است. بعد از یائسگی چکاپ منظم برای استخوان و قلب اهمیت بیشتری دارد.","cta_label":"دیدن چکاپ‌ها","cta_target":"/checkups"},"translations":{"en":{"a":{"title":"A checkup is due","body":"It is time for {meno_due_checkup}. Regular checks matter more for your bones and heart after menopause.","cta_label":"See my checkups","cta_target":"/checkups"}}}}', '[{"op":"and","items":[{"fact":"meno.checkups_due","op":"gte","value":1},{"fact":"meno.checkups_overdue","op":"eq","value":0}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('meno.tip_stage_peri', 'Menopause tip: perimenopause', 'info', 'content', 150, 'daily_advice', '{"a":{"title":"پیش‌یائسگی","body":"پریودها ممکن است نامنظم، کم یا زیاد شوند و علائم تازه بیایند. ثبت پریود و علائم کمک می‌کند الگوها را ببینی و با پزشک دقیق‌تر حرف بزنی."},"translations":{"en":{"a":{"title":"Perimenopause","body":"Periods may become irregular, lighter or heavier, and new symptoms may start. Logging periods and symptoms helps you see patterns and talk to your doctor in detail."}}}}', '[{"op":"and","items":[{"fact":"meno.stage","op":"eq","value":"peri"}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('meno.tip_stage_meno', 'Menopause tip: menopause', 'info', 'content', 150, 'daily_advice', '{"a":{"title":"یائسگی","body":"از ۱۲ ماه گذشته، یعنی وارد یائسگی شده‌ای. از این به بعد هر خونریزی یا لکه‌بینی را ثبت کن و به پزشک خبر بده."},"translations":{"en":{"a":{"title":"Menopause","body":"It has been more than 12 months, which means you have reached menopause. From now on, log any bleeding or spotting and tell your doctor."}}}}', '[{"op":"and","items":[{"fact":"meno.stage","op":"eq","value":"meno"}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('meno.tip_stage_post', 'Menopause tip: postmenopause', 'info', 'content', 150, 'daily_advice', '{"a":{"title":"پس از یائسگی","body":"در این سال‌ها مراقبت از استخوان و قلب مهم‌تر می‌شود. چکاپ‌های منظم را دنبال کن و هر خونریزی یا لکه‌بینی را به پزشک بگو."},"translations":{"en":{"a":{"title":"Postmenopause","body":"In these years caring for your bones and heart matters more. Keep up with regular checkups and tell your doctor about any bleeding or spotting."}}}}', '[{"op":"and","items":[{"fact":"meno.stage","op":"eq","value":"post"}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('meno.tip_stage_unsure', 'Menopause tip: stage not known', 'info', 'content', 150, 'daily_advice', '{"a":{"title":"مطمئن نیستم","body":"اگر مطمئن نیستی کجای مسیر هستی، تاریخ تقریبی آخرین پریود کمک می‌کند. ۱۲ ماه بدون پریود یعنی یائسگی؛ پزشک می‌تواند دقیق‌تر بگوید."},"translations":{"en":{"a":{"title":"Not sure","body":"If you are not sure where you are, the approximate date of your last period helps. 12 months without a period means menopause; your doctor can tell you more."}}}}', '[{"op":"and","items":[{"fact":"meno.stage","op":"eq","value":"unsure"}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('cond.heavy_pain', 'Condition nudge: strong pain on several days', 'suggestion', 'content', 450, 'alerts_inbox', '{"a":{"title":"درد شدید در چند روز","body":"در این چرخه {cond_pain_days} روز درد ۷ یا بیشتر ثبت کرده‌ای. دفترچه درد کمک می‌کند تو و پزشکت الگوی آن را ببینید.","cta_label":"باز کردن دفترچه درد","cta_target":"/programs/pain"},"translations":{"en":{"a":{"title":"Strong pain on several days","body":"You logged pain of 7 or more on {cond_pain_days} days this cycle. A pain diary helps you and your doctor see the pattern.","cta_label":"Open the pain diary","cta_target":"/programs/pain"}}}}', '[{"op":"and","items":[{"fact":"cond.heavy_pain_days","op":"gte","value":2},{"fact":"cond.programs","op":"nin","value":["endo"]}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('cond.heavy_bleeding', 'Condition nudge: heavy flow on several days', 'suggestion', 'content', 440, 'alerts_inbox', '{"a":{"title":"خونریزی سنگین در چند روز","body":"در این چرخه {cond_bleeding_days} روز خونریزی سنگین ثبت کرده‌ای. جدول نوار بهداشتی (PBAC) مقدار خونریزی را می‌سنجد تا بشود بررسی‌اش کرد.","cta_label":"باز کردن جدول خونریزی","cta_target":"/programs/bleeding"},"translations":{"en":{"a":{"title":"Heavy flow on several days","body":"You logged heavy flow on {cond_bleeding_days} days this cycle. The pad chart (PBAC) measures how much you bleed so it can be checked.","cta_label":"Open the bleeding chart","cta_target":"/programs/bleeding"}}}}', '[{"op":"and","items":[{"fact":"cond.heavy_bleeding_days","op":"gte","value":2},{"fact":"cond.programs","op":"nin","value":["heavy_bleeding"]}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW())
ON DUPLICATE KEY UPDATE `id` = `id`;
-- +goose StatementEnd

-- +goose Down
DELETE FROM `message_inbox` WHERE `rule_key` LIKE 'meno.%' OR `rule_key` LIKE 'cond.%';
DELETE FROM `message_rules` WHERE `rule_key` IN ('meno.postmenopausal_bleeding', 'meno.checkup_overdue',
  'meno.score_worsened', 'meno.hrt_review', 'meno.checkup_due', 'meno.tip_stage_peri', 'meno.tip_stage_meno',
  'meno.tip_stage_post', 'meno.tip_stage_unsure', 'cond.heavy_pain', 'cond.heavy_bleeding');
